import{_ as e}from"./chunks/wireless.B7WNJ_4V.js";import{_ as r,c as t,o,ae as s}from"./chunks/framework.CDjunVez.js";const p=JSON.parse('{"title":"无线红石系统","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/wireless_redstone.md","filePath":"zh/manual/wireless_redstone.md"}'),l={name:"zh/manual/wireless_redstone.md"};function n(i,a,_,d,h,c){return o(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="无线红石系统" tabindex="-1">无线红石系统 <a class="header-anchor" href="#无线红石系统" aria-label="Permalink to &quot;无线红石系统&quot;">​</a></h1><p>模组提供了简洁高效的全局无线红石传输方案，极大地简化了大型建筑或跨区域音乐系统的布线工作。</p><h2 id="核心方块" tabindex="-1">核心方块 <a class="header-anchor" href="#核心方块" aria-label="Permalink to &quot;核心方块&quot;">​</a></h2><p><img src="'+e+'" alt="WirelessRedstone"></p><h3 id="_1-红石信号发送器" tabindex="-1">1. 红石信号发送器 <a class="header-anchor" href="#_1-红石信号发送器" aria-label="Permalink to &quot;1. 红石信号发送器&quot;">​</a></h3><ul><li><strong>作用</strong>: 当发送器接收到红石信号（充能）时，它会激活整个世界的无线网络。</li><li><strong>机制</strong>: 只要世界中存在<strong>至少一个</strong>处于充能状态的发送器，无线网络即为“开启”状态。</li></ul><h3 id="_2-红石信号接收器" tabindex="-1">2. 红石信号接收器 <a class="header-anchor" href="#_2-红石信号接收器" aria-label="Permalink to &quot;2. 红石信号接收器&quot;">​</a></h3><ul><li><strong>作用</strong>: 监听无线网络的状态。当无线网络处于“开启”状态时，接收器会向周围输出 15 级强度的红石信号。</li><li><strong>机制</strong>: 接收器可以作为普通的红石源使用，触发音符盒、门、活塞等。</li></ul><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><ul><li><strong>远程控制</strong>: 在一个中心控制台布置发送器，控制远处不同区域的音符盒阵列。</li><li><strong>同步播放</strong>: 将多个区域的接收器连接到对应的音符盒，通过一个主信号实现跨区域同步发声。</li></ul>',10)])])}const g=r(l,[["render",n]]);export{p as __pageData,g as default};
